import{_ as p,a0 as r,w as o,s as d,I as a,x as n,a1 as t,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何使用 VTY Shell 配置路由器 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 VTY Shell 配置路由器 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 VTY Shell 配置路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 VTY Shell 配置路由器 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200520 How to configure your router using VTY shell","title":"如何使用 VTY Shell 配置路由器","tag":"202005","desc":""},"relativePath":"202005/20200520 How to configure your router using VTY shell.md","filePath":"[post].md"}'),u={name:"202005/20200520 How to configure your router using VTY shell.md"};function h(g,s,f,c,k,b){const e=r("Link");return o(),d("div",null,[s[33]||(s[33]=a("h1",{id:"如何使用-vty-shell-配置路由器",tabindex:"-1"},[n("如何使用 VTY Shell 配置路由器 "),a("a",{class:"header-anchor",href:"#如何使用-vty-shell-配置路由器","aria-label":"Permalink to “如何使用 VTY Shell 配置路由器”"},"​")],-1)),s[34]||(s[34]=a("blockquote",null,[a("p",null,"FRR（free range routing）给了你实现多种协议的选择。本指南将帮助你入门。")],-1)),s[35]||(s[35]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/31/122310xi9aag5iqihqgcxl.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("最近，我写了一篇文章，解释了如何使用 ",-1)),t(e,{href:"https://linux.cn/article-12199-1.html"},{default:i(()=>[...s[0]||(s[0]=[n("Quagga",-1)])]),_:1}),s[2]||(s[2]=n(" 路由套件实现",-1)),s[3]||(s[3]=a("ruby",null,[n("开放式最短路径优先"),a("rt",null,"Open Shortest Path First")],-1)),s[4]||(s[4]=n("（OSPF）。可以使用多个软件套件代替 Quagga 来实现不同的路由协议。其中一种是 FRR（free range routing）。",-1))]),s[36]||(s[36]=a("h3",{id:"frr",tabindex:"-1"},[n("FRR "),a("a",{class:"header-anchor",href:"#frr","aria-label":"Permalink to “FRR”"},"​")],-1)),a("p",null,[t(e,{href:"https://en.wikipedia.org/wiki/FRRouting"},{default:i(()=>[...s[5]||(s[5]=[n("FRR",-1)])]),_:1}),s[6]||(s[6]=n(" 是一个路由软件套件，它衍生自 Quagga，并在 GNU GPL2 许可下分发。与 Quagga 一样，它为类 Unix 平台提供了所有主要路由协议的实现，例如 OSPF、",-1)),s[7]||(s[7]=a("ruby",null,[n("路由信息协议"),a("rt",null,"Routing Information Protocol")],-1)),s[8]||(s[8]=n("（RIP）、",-1)),s[9]||(s[9]=a("ruby",null,[n("边界网关协议"),a("rt",null,"Border Gateway Protocol")],-1)),s[10]||(s[10]=n("（BGP） 和",-1)),s[11]||(s[11]=a("ruby",null,[n("中间系统到中间系统"),a("rt",null,"Intermediate system-to-intermediate system")],-1)),s[12]||(s[12]=n(" （IS-IS）。",-1))]),s[37]||(s[37]=l('<p>开发了 Quagga 的一些公司，例如 Big Switch Networks、Cumulus、Open Source Routing 和 6wind，创建了 FRR 以在 Quagga 的良好基础上进行改善。</p><h4 id="体系结构" tabindex="-1">体系结构 <a class="header-anchor" href="#体系结构" aria-label="Permalink to “体系结构”">​</a></h4><p>FRR 是一组守护进程，它们可以共同构建路由表。每个主协议都在其自己的守护进程中实现，并且这些守护进程与独立于协议的核心守护进程 Zebra 通信，后者提供内核路由表更新、接口查找以及不同路由协议之间路由的重新分配。每个特定协议的守护进程负责运行相关协议并根据交换的信息构建路由表。</p><p><img src="https://opensource.com/sites/default/files/uploads/frr_architecture.png" alt="FRR architecture" title="FRR architecture"></p><h3 id="vty-shell" tabindex="-1">VTY shell <a class="header-anchor" href="#vty-shell" aria-label="Permalink to “VTY shell”">​</a></h3>',5)),a("p",null,[t(e,{href:"http://docs.frrouting.org/projects/dev-guide/en/latest/vtysh.html"},{default:i(()=>[...s[13]||(s[13]=[n("VTYSH",-1)])]),_:1}),s[14]||(s[14]=n(" 是 FRR 路由引擎的集成 shell。它将每个守护进程中定义的所有 CLI 命令合并，并在单个 shell 中将它们呈现给用户。它提供了类似于 Cisco 的命令行模式，并且许多命令与 Cisco IOS 命令相似。CLI 有不同的模式，某些命令仅在特定模式下可用。",-1))]),s[38]||(s[38]=l('<h3 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h3><p>在本教程中，我们将使用 FRR 配置动态路由来实现路由信息协议（RIP）。我们可以通过两种方式来做到这一点：在编辑器中编辑协议守护进程配置文件或使用 VTY Shell。在此例中，我们将使用 VTY shell。我们的设置包括两个名为 Alpha 和 Beta 的 CentOS 7.7 主机。这两台主机都有两个网络接口，并共享对 192.168.122.0/24 网络的访问。我们将广播 10.12.11.0/24 和 10.10.10.0/24 网络的路由。</p><p>对于主机 Alpha：</p><ul><li>eth0 IP：192.168.122.100/24</li><li>网关：192.168.122.1</li><li>eth1 IP：10.10.10.12/24</li></ul><p>对于主机 Beta：</p><ul><li>eth0 IP：192.168.122.50/24</li><li>网关：192.168.122.1</li><li>eth1 IP：10.12.11.12/24</li></ul><h4 id="安装软件包" tabindex="-1">安装软件包 <a class="header-anchor" href="#安装软件包" aria-label="Permalink to “安装软件包”">​</a></h4>',7)),a("p",null,[s[16]||(s[16]=n("首先，我们需要在两台主机上都安装 FRR 软件包。可以按照",-1)),t(e,{href:"http://docs.frrouting.org/projects/dev-guide/en/latest/building-frr-for-centos7.html"},{default:i(()=>[...s[15]||(s[15]=[n("官方 FRR 文档",-1)])]),_:1}),s[17]||(s[17]=n("中的说明进行操作。",-1))]),s[39]||(s[39]=l(`<h4 id="启用-ip-转发" tabindex="-1">启用 IP 转发 <a class="header-anchor" href="#启用-ip-转发" aria-label="Permalink to “启用 IP 转发”">​</a></h4><p>对于路由，我们需要在两台主机上都启用 IP 转发，因为这将由 Linux 内核执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysctl -w net.ipv4.conf.all.forwarding = 1</span></span>
<span class="line"><span>sysctl -w net.ipv6.conf.all.forwarding = 1</span></span>
<span class="line"><span>sysctl -p</span></span></code></pre></div><h4 id="启用-ripd-守护进程" tabindex="-1">启用 RIPD 守护进程 <a class="header-anchor" href="#启用-ripd-守护进程" aria-label="Permalink to “启用 RIPD 守护进程”">​</a></h4><p>安装后，所有配置文件将保存在 <code>/etc/frr</code> 目录中。 必须通过编辑 <code>/etc/frr/daemons</code> 文件显式启用守护进程。该文件确定启动 FRR 服务时激活哪些守护进程。要启用特定的守护进程，只需将相应的 <code>no</code> 改为 <code>yes</code>。之后的服务重启将启动守护进程。</p><p><img src="https://opensource.com/sites/default/files/uploads/frr_daemon_restart.png" alt="FRR daemon restart" title="FRR daemon restart"></p><h4 id="防火墙配置" tabindex="-1">防火墙配置 <a class="header-anchor" href="#防火墙配置" aria-label="Permalink to “防火墙配置”">​</a></h4><p>由于 RIP 协议使用 UDP 作为传输协议，并被分配了 520 端口，因此我们需要在 <code>firewalld</code> 配置中允许该端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-port=520/udp –permanent</span></span>
<span class="line"><span>firewalld-cmd -reload</span></span></code></pre></div><p>现在，我们可以使用以下命令启动 FRR 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start frr</span></span></code></pre></div><h4 id="使用-vty-进行配置" tabindex="-1">使用 VTY 进行配置 <a class="header-anchor" href="#使用-vty-进行配置" aria-label="Permalink to “使用 VTY 进行配置”">​</a></h4><p>现在，我们需要使用 VTY Shell 配置 RIP。</p><p>在主机 Alpha 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# vtysh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello, this is FRRouting (version 7.2RPKI).</span></span>
<span class="line"><span>Copyright 1996-2005 Kunihiro Ishiguro, et al.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alpha# configure terminal</span></span>
<span class="line"><span>alpha(config)# router rip</span></span>
<span class="line"><span>alpha(config-router)# network 192.168.122.0/24</span></span>
<span class="line"><span>alpha(config-router)# network 10.10.10.0/24</span></span>
<span class="line"><span>alpha(config-router)# route 10.10.10.5/24</span></span>
<span class="line"><span>alpha(config-router)# do write</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>alpha(config-router)# do write memory</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>alpha(config-router)# exit</span></span></code></pre></div><p>类似地，在主机 Beta 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# vtysh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello, this is FRRouting (version 7.2RPKI).</span></span>
<span class="line"><span>Copyright 1996-2005 Kunihiro Ishiguro, et al.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>beta# configure terminal</span></span>
<span class="line"><span>beta(config)# router rip</span></span>
<span class="line"><span>beta(config-router)# network 192.168.122.0/24</span></span>
<span class="line"><span>beta(config-router)# network 10.12.11.0/24</span></span>
<span class="line"><span>beta(config-router)# do write</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/zebra.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>beta(config-router)# do write memory</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/zebra.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>beta(config-router)# exit</span></span></code></pre></div><p>完成后，像下面这样检查两台主机路由：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 dev eth1 proto kernel scope link src 10.10.10.12 metric 101</span></span>
<span class="line"><span>10.12.11.0/24 via 192.168.122.50 dev eth0 proto 189 metric 20</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.100 metric 100</span></span></code></pre></div><p>我们可以看到 Alpha 上的路由表通过 <code>192.168.122.50</code> 包含了 <code>10.12.11.0/24</code> 的条目，它是通过 RIP 提供的。</p><p>类似地，在 Beta 上，该表通过 <code>192.168.122.100</code> 包含了 <code>10.10.10.0/24</code> 的条目。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 via 192.168.122.100 dev eth0 proto 189 metric 20</span></span>
<span class="line"><span>10.12.11.0/24 dev eth1 proto kernel scope link src 10.12.11.12 metric 101</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.50 metric 100</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如你所见，设置和配置相对简单。要增加复杂性，我们可以向路由器添加更多的网络接口，以为更多的网络提供路由。可以在编辑器中编辑配置文件来进行配置，但是使用 VTY Shell 在单个组合会话中为我们提供了所有 FRR 守护进程的前端。</p><hr>`,25)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/20/5/vty-shell"},{default:i(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/20/5/vty-shell",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/noisybotnet"},{default:i(()=>[...s[20]||(s[20]=[n("M Umer",-1)])]),_:1}),s[25]||(s[25]=n(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[30]||(s[30]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[29]||(s[29]=[n("Linux中国",-1)])]),_:1}),s[32]||(s[32]=n(" 荣誉推出",-1))])])}const C=p(u,[["render",h]]);export{y as __pageData,C as default};
